output_text:
[
  {
    "id": "ban_carts_in_single_file_shelf_aisles",
    "text": "Carts must not be taken into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelfFlankedSingleFileAisle": {
          "and": [
            "singleFile",
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shelfFlankedSingleFileAisle"
        ]
      }
    }
  },
  {
    "id": "ban_entering_single_file_with_cart",
    "text": "An agent may not move from a wider aisle into a single-file aisle while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "notSingleFile": {
          "not": "singleFile"
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "notSingleFile",
              "MOVE"
            ]
          },
          "post": "singleFile"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "must_drop_cart_at_upper_aisle_mouth",
    "text": "When using a cart interaction point at the mouth of an upper single-file aisle, the agent must leave the cart behind before entering.",
    "abstraction": {
      "state_properties": {
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideMouth": {
          "and": [
            "upperAisleMouth",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "wideMouth",
          "hasCart",
          "INTERACT"
        ]
      },
      "discharge": {
        "not": "hasCart"
      }
    }
  },
  {
    "id": "retrieve_cart_after_upper_item_pick",
    "text": "After picking an item in a cart-free upper single-file shelf aisle, the agent must return and retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "upperShelfAisle": {
          "and": [
            "singleFile",
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "withoutCart": {
          "not": "hasCart"
        }
      },
      "events": {
        "upperItemPickWithoutCart": {
          "pre": {
            "and": [
              "upperShelfAisle",
              "withoutCart",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "upperItemPickWithoutCart",
      "discharge": "hasCart"
    }
  },
  {
    "id": "drop_cart_only_in_wide_parking_bays",
    "text": "A cart may only be abandoned by interaction in a designated wide parking bay, not in ordinary shopping aisles.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartParkingBay": {
          "and": [
            "wideAisle",
            "upperAisleMouth"
          ]
        }
      },
      "events": {
        "abandonCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "abandonCart",
          {
            "not": "cartParkingBay"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_wander_cartless_in_cart_compatible_aisles",
    "text": "Except at cart-parking bays or inside single-file shelf aisles, the agent should not be away from the cart in cart-compatible aisles.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartCompatibleAisle": {
          "ge": [
            "freeWidthH",
            2
          ]
        },
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessAwayFromPermittedArea": {
          "and": [
            {
              "not": "hasCart"
            },
            "cartCompatibleAisle",
            {
              "not": "cartParkingBay"
            },
            {
              "not": "singleFile"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessAwayFromPermittedArea"
    }
  },
  {
    "id": "must_retrieve_cart_after_entering_cartless_single_file",
    "text": "Anyone who enters a single-file shelf aisle without a cart must later retrieve a cart from a parking bay.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelfFlankedSingleFileAisle": {
          "and": [
            "singleFile",
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartlessSingleFileVisit": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "shelfFlankedSingleFileAisle"
            ]
          },
          "post": null
        },
        "retrieveCartAtBay": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "cartParkingBay",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessSingleFileVisit",
      "discharge": "retrieveCartAtBay"
    }
  },
  {
    "id": "ban_cart_upper_shelf_interactions",
    "text": "Items located in upper single-file shelf aisles must be collected without holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "upperPickZone": {
          "and": [
            "singleFile",
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartHeldUpperShelfInteraction": {
          "pre": {
            "and": [
              "hasCart",
              "upperPickZone",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartHeldUpperShelfInteraction"
    }
  }
]
